void test_sensors_01(void)
{
    mpu6050_sample_t sample = {0.0F, 0.0F, 1.0F};

    sensors_calibrate(100U, &sample);
    TEST_ASSERT_FALSE(sensors_snapshot()->is_calibrated);

    sensors_calibrate(1099U, &sample);
    TEST_ASSERT_FALSE(sensors_snapshot()->is_calibrated);

    sensors_calibrate(1100U, &sample);
    TEST_ASSERT_TRUE(sensors_snapshot()->is_calibrated);
}

void test_sensors_02(void)
{
    mpu6050_sample_t sample = {APP_CALIBRATION_FLAT_G,
                               -APP_CALIBRATION_FLAT_G,
                               1.0F};

    sensors_calibrate(0U, &sample);
    sensors_calibrate(APP_CALIBRATION_MS, &sample);

    TEST_ASSERT_TRUE(sensors_snapshot()->is_calibrated);
}

void test_sensors_03(void)
{
    mpu6050_sample_t flat = {0.0F, 0.0F, 1.0F};
    mpu6050_sample_t nonflat = {APP_CALIBRATION_FLAT_G + 0.001F,
                                0.0F,
                                1.0F};

    sensors_calibrate(100U, &flat);
    sensors_calibrate(500U, &nonflat);
    sensors_calibrate(1000U, &flat);
    sensors_calibrate(1999U, &flat);
    TEST_ASSERT_FALSE(sensors_snapshot()->is_calibrated);

    sensors_calibrate(2000U, &flat);
    TEST_ASSERT_TRUE(sensors_snapshot()->is_calibrated);
}

